from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions
from .models import SecureDocumentVault

class DocumentVaultArraySearchView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request):
        tag_query = request.query_params.get('tag')
        if not tag_query:
            return Response({"results": []})

        # Constrain ArrayField query to documents belonging to the authenticated tenant
        documents = SecureDocumentVault.objects.filter(
            tenant=request.user.tenant,
            classification_labels__contains=[tag_query]
        ).values('id', 'title', 'file_url', 'classification_labels')

        return Response({"tag": tag_query, "documents": list(documents)})
